# The symbolic inequalities above imply that scaling o by 0.67 changes
# the public modular label precisely on these integer weighted scores.
changed_scores = {2, 3, 4, 5, 6, 7, 11, 12, 13, 14}

# Generate score multiplicities algebraically, without input enumeration.
t = sp.Symbol("t")
program = TASK["public"]["declared_programs"][0]
prefix_polynomial = sp.Integer(1)
domain_polynomial = sp.Integer(0)
for position_weight in program["positions"]:
    prefix_polynomial *= sum(
        t ** (position_weight * code) for code in program["codes"]
    )
    domain_polynomial += prefix_polynomial

counts = {
    int(exponent[0]): int(coefficient)
    for exponent, coefficient in sp.Poly(
        sp.expand(domain_polynomial), t
    ).terms()
}
total = sum(counts.values())
assert total == 363

scaled_fraction = sum(counts.get(s, 0) for s in changed_scores) / total

# Zeroed w1 rows leave only b1; its largest bias selects class 1.
constant_fraction = sum(
    count for score, count in counts.items() if (score + 1) % 3 != 1
) / total

sub = {
    "effects": {
        "f0": [0.0, 0.0],
        "f1": [scaled_fraction, scaled_fraction],
        "f2": [0.0, constant_fraction],
        "f3": [constant_fraction, scaled_fraction],
    }
}
check_submission(sub)
import json
with open("/work/submission.json", "w") as f:
    json.dump(sub, f)
print(sub)
